insert into public.questions (id, kind, prompt, options, marks, image_url) values ('cb705ad5-95d0-55f4-b59f-502fedc03a76', 'short', 'Distinguish between the fundamental and realized niche of a species.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cb705ad5-95d0-55f4-b59f-502fedc03a76', 'The fundamental niche is the full range of conditions and resources a species could potentially occupy [1]; the realized niche is the part it actually occupies because of competition with other species [1].', 'The fundamental niche is the full range of conditions and resources a species could potentially occupy [1]; the realized niche is the part it actually occupies because of competition with other species [1].', '[{"text": "Marking point 1", "any": ["potential", "could", "full range", "without competition"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["actual", "actually", "competition", "smaller", "occupies"], "all": [], "marks": 1}]'::jsonb, 'The fundamental niche is the full range of conditions and resources a species could potentially occupy [1]; the realized niche is the part it actually occupies because of competition with other species [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('27029837-c123-5a33-ae13-4f1a6e939127', 'cb705ad5-95d0-55f4-b59f-502fedc03a76', 18);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f1973533-67bd-504a-b8a9-1b16c3ce7e90', 'short', 'Explain the principle of competitive exclusion.', '[]'::jsonb, 2, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f1973533-67bd-504a-b8a9-1b16c3ce7e90', 'Two species competing for the same limiting resource in the same niche [1] cannot coexist indefinitely: one will exclude the other from that area [1].', 'Two species competing for the same limiting resource in the same niche [1] cannot coexist indefinitely: one will exclude the other from that area [1].', '[{"text": "Marking point 1", "any": ["same niche", "same resource", "compete"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["exclude", "one species", "eliminat", "cannot coexist"], "all": [], "marks": 1}]'::jsonb, 'Two species competing for the same limiting resource in the same niche [1] cannot coexist indefinitely: one will exclude the other from that area [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
