insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('45ae9b71-4d2f-5bdd-b5b9-7dd81a77db1c', 'Chthamalus barnacles can survive lower on the shore [1], but are outcompeted by Balanus there, so their realized niche is restricted to the upper shore [1].', 'Chthamalus barnacles can survive lower on the shore [1], but are outcompeted by Balanus there, so their realized niche is restricted to the upper shore [1].', '[{"text": "Marking point 1", "any": ["barnacle", "chthamalus", "balanus", "example"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["competition", "excluded", "outcompeted"], "all": [], "marks": 1}]'::jsonb, 'Chthamalus barnacles can survive lower on the shore [1], but are outcompeted by Balanus there, so their realized niche is restricted to the upper shore [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
