insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e56dcb66-ce14-5695-8c77-9cb7d74a32f5', 'Holozoic organisms ingest food and digest it internally [1]; saprotrophs secrete enzymes onto dead organic matter and digest it externally, absorbing the products [1].', 'Holozoic organisms ingest food and digest it internally [1]; saprotrophs secrete enzymes onto dead organic matter and digest it externally, absorbing the products [1].', '[{"text": "Marking point 1", "any": ["ingest", "internal", "inside the body", "swallow"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["external", "outside", "secrete enzymes", "onto"], "all": [], "marks": 1}]'::jsonb, 'Holozoic organisms ingest food and digest it internally [1]; saprotrophs secrete enzymes onto dead organic matter and digest it externally, absorbing the products [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
