insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('352e7aed-f61b-585d-9c41-cae9a24c235e', 'A habitat is the place where an organism lives [1]; a niche is its role in the ecosystem, including its feeding, interactions and tolerance of conditions [1].', 'A habitat is the place where an organism lives [1]; a niche is its role in the ecosystem, including its feeding, interactions and tolerance of conditions [1].', '[{"text": "Marking point 1", "any": ["place", "where it lives", "location"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["role", "interactions", "how it feeds", "function"], "all": [], "marks": 1}]'::jsonb, 'A habitat is the place where an organism lives [1]; a niche is its role in the ecosystem, including its feeding, interactions and tolerance of conditions [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
