insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3272011c-1aaa-5d8b-82d3-964a55b10379', 'Large flat molars with thick enamel were used for grinding and chewing tough, hard food [1]; such as seeds, roots and other plant material (a mainly herbivorous diet) [1].', 'Large flat molars with thick enamel were used for grinding and chewing tough, hard food [1]; such as seeds, roots and other plant material (a mainly herbivorous diet) [1].', '[{"text": "Marking point 1", "any": ["grind", "chew", "tough", "hard"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["plant", "seeds", "roots", "herbivor", "vegetation"], "all": [], "marks": 1}]'::jsonb, 'Large flat molars with thick enamel were used for grinding and chewing tough, hard food [1]; such as seeds, roots and other plant material (a mainly herbivorous diet) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
