insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cb705ad5-95d0-55f4-b59f-502fedc03a76', 'The fundamental niche is the full range of conditions and resources a species could potentially occupy [1]; the realized niche is the part it actually occupies because of competition with other species [1].', 'The fundamental niche is the full range of conditions and resources a species could potentially occupy [1]; the realized niche is the part it actually occupies because of competition with other species [1].', '[{"text": "Marking point 1", "any": ["potential", "could", "full range", "without competition"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["actual", "actually", "competition", "smaller", "occupies"], "all": [], "marks": 1}]'::jsonb, 'The fundamental niche is the full range of conditions and resources a species could potentially occupy [1]; the realized niche is the part it actually occupies because of competition with other species [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('60e2e77f-03c9-5dc2-87f7-cd32ba118181', 'cb705ad5-95d0-55f4-b59f-502fedc03a76', 18);
