insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f1973533-67bd-504a-b8a9-1b16c3ce7e90', 'Two species competing for the same limiting resource in the same niche [1] cannot coexist indefinitely: one will exclude the other from that area [1].', 'Two species competing for the same limiting resource in the same niche [1] cannot coexist indefinitely: one will exclude the other from that area [1].', '[{"text": "Marking point 1", "any": ["same niche", "same resource", "compete"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["exclude", "one species", "eliminat", "cannot coexist"], "all": [], "marks": 1}]'::jsonb, 'Two species competing for the same limiting resource in the same niche [1] cannot coexist indefinitely: one will exclude the other from that area [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
