insert into public.questions (id, kind, prompt, options, marks, image_url) values ('f696c34d-3d40-50c9-becf-4a9f788bd65f', 'short', 'Explain the annual fluctuations in CO₂ concentration shown by the Keeling Curve.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mauna_Loa_CO2_monthly_mean_concentration.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f696c34d-3d40-50c9-becf-4a9f788bd65f', 'In the northern hemisphere summer [1] photosynthesis exceeds respiration, removing CO₂, so concentration falls [1]; in winter, when photosynthesis is reduced, respiration and combustion release more CO₂, so it rises [1].', 'In the northern hemisphere summer [1] photosynthesis exceeds respiration, removing CO₂, so concentration falls [1]; in winter, when photosynthesis is reduced, respiration and combustion release more CO₂, so it rises [1].', '[{"text": "Marking point 1", "any": ["summer", "growing season"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["more photosynthesis", "photosynthesis"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["winter", "respiration", "leaves fall"], "all": [], "marks": 1}]'::jsonb, 'In the northern hemisphere summer [1] photosynthesis exceeds respiration, removing CO₂, so concentration falls [1]; in winter, when photosynthesis is reduced, respiration and combustion release more CO₂, so it rises [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
