insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ac1d4e2a-2b1d-5e64-80ad-73ffaebeecfb', 'CO₂ concentration has risen steadily from about 315 ppm in 1958 to over 420 ppm [1], because combustion of fossil fuels and deforestation release more CO₂ than is absorbed [1].', 'CO₂ concentration has risen steadily from about 315 ppm in 1958 to over 420 ppm [1], because combustion of fossil fuels and deforestation release more CO₂ than is absorbed [1].', '[{"text": "Marking point 1", "any": ["increase", "rising", "315", "420"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fossil fuel", "combustion", "deforestation", "burning"], "all": [], "marks": 1}]'::jsonb, 'CO₂ concentration has risen steadily from about 315 ppm in 1958 to over 420 ppm [1], because combustion of fossil fuels and deforestation release more CO₂ than is absorbed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
